@Test
public void testDuplicateRpcPort() throws Exception {
    @SuppressWarnings("rawtypes")
    Context context = mock(Context.class);
    Configuration conf = new Configuration();
    conf.setInt("mapred.task.partition", 9);
    conf.setInt(GiraphJob.MAX_WORKERS, 13);
    when(context.getConfiguration()).thenReturn(conf);
    when(context.getJobID()).thenReturn(new JobID());
    RPCCommunications<IntWritable, IntWritable, IntWritable, IntWritable> comm1 = new RPCCommunications<IntWritable, IntWritable, IntWritable, IntWritable>(context, null, null);
    RPCCommunications<IntWritable, IntWritable, IntWritable, IntWritable> comm2 = new RPCCommunications<IntWritable, IntWritable, IntWritable, IntWritable>(context, null, null);
    RPCCommunications<IntWritable, IntWritable, IntWritable, IntWritable> comm3 = new RPCCommunications<IntWritable, IntWritable, IntWritable, IntWritable>(context, null, null);
    assertEquals(comm1.getPort(), 30009);
    assertEquals(comm2.getPort(), 30109);
    assertEquals(comm3.getPort(), 30209);
}

