    writer.initialize(tac);
    writer.writeVertex(vertex);
    verify(tw).write(expected, null);
    verify(vertex, times(0)).getEdges();
    verify(vertex, times(0)).getEdgeValue(Matchers.<WritableComparable>any());
}

