@Test
public void testIndexMustHaveValue() throws IOException, InterruptedException {
    String input = "123";
    when(rr.getCurrentValue()).thenReturn(new Text(input));
    LongDoubleDoubleAdjacencyListVertexInputFormat.VertexReader<BooleanWritable> vr = new LongDoubleDoubleAdjacencyListVertexInputFormat.VertexReader<BooleanWritable>(rr);
    vr.initialize(null, tac);
    try {
        vr.nextVertex();
        vr.getCurrentVertex();
        fail("Should have thrown an IllegalArgumentException");
    } catch (IllegalArgumentException iae) {
        assertTrue(iae.getMessage().startsWith("Line did not split correctly: "));
    }
}

