/**
 * prepare a vertex for use in a unit test by setting its internal state and injecting mocked
 * dependencies,
 *
 * @param vertex
 * @param superstep the superstep to emulate
 * @param vertexId initial vertex id
 * @param vertexValue initial vertex value
 * @param isHalted initial halted state of the vertex
 * @param <I> vertex id
 * @param <V> vertex data
 * @param <E> edge data
 * @param <M> message data
 * @return
 * @throws Exception
 */
public static <I extends WritableComparable, V extends Writable, E extends Writable, M extends Writable> MockedEnvironment<I, V, E, M> prepareVertex(Vertex<I, V, E, M> vertex, long superstep, I vertexId, V vertexValue, boolean isHalted) throws Exception {
    MockedEnvironment<I, V, E, M> env = new MockedEnvironment<I, V, E, M>();
    Mockito.when(env.getGraphState().getSuperstep()).thenReturn(superstep);
    Mockito.when(env.getGraphState().getContext()).thenReturn(env.getContext());
    Mockito.when(env.getContext().getConfiguration()).thenReturn(env.getConfiguration());
    Mockito.when(env.getGraphState().getWorkerCommunications()).thenReturn(env.getCommunications());
    ReflectionUtils.setField(vertex, "id", vertexId);
    ReflectionUtils.setField(vertex, "value", vertexValue);
    ReflectionUtils.setField(vertex, "graphState", env.getGraphState());
    ReflectionUtils.setField(vertex, "halt", isHalted);
    return env;
}

